<script setup lang="ts">import{reactive,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{authAPI}from'../../api/auth';import{APIError}from'../../api/client';import AuthShell from'../../components/AuthShell.vue';import{useToast}from'../../composables/useToast';const route=useRoute(),router=useRouter(),toast=useToast(),form=reactive({token:String(route.query.token||''),name:'',password:'',confirm:''}),error=ref('');async function submit(){error.value='';if(form.password.length<12||form.password.length>128){error.value='密码长度必须为 12–128 个字符';return}if(form.password!==form.confirm){error.value='两次输入的密码不一致';return}try{await authAPI.activateTeacher({token:form.token,name:form.name,password:form.password});toast.success('老师账号已激活，请登录');await router.replace('/login')}catch(e){error.value=e instanceof APIError?e.message:'激活失败'}}</script>
<template><AuthShell><section class="auth-card panel"><RouterLink to="/login">← 返回登录</RouterLink><h1>激活老师账号</h1><form @submit.prevent="submit"><label v-if="!route.query.token">邀请 Token<input v-model="form.token" required/></label><label>姓名<input v-model="form.name" required/></label><label>设置密码<input v-model="form.password" type="password" minlength="12" maxlength="128" required/></label><label>确认密码<input v-model="form.confirm" type="password" minlength="12" maxlength="128" required/></label><p v-if="error" class="error">{{error}}</p><button class="button primary wide">完成激活</button></form></section></AuthShell></template>
